using ASMILE.BO.Core.FrontOffice.Foundation.Identifiers;

namespace ASMILE.BO.Core.FrontOffice.HotelMasterData;

public enum HotelHousekeepingRuleKind { DailyCleaning = 1, CheckOutCleaning = 2, TurnDown = 3, Inspection = 4, DeepCleaning = 5, LinenChange = 6, Maintenance = 7 }

public sealed class HotelHousekeepingRuleProfile
{
    private HotelHousekeepingRuleProfile() { }
    public Guid HotelHousekeepingRuleProfileId { get; private set; } public Guid PropertyId { get; private set; } public string Code { get; private set; } = string.Empty; public string Name { get; private set; } = string.Empty; public HotelHousekeepingRuleKind Kind { get; private set; } public int Priority { get; private set; } public string Department { get; private set; } = string.Empty; public int SlaMinutes { get; private set; } public bool RequiresInspection { get; private set; } public bool AutoCreateTask { get; private set; } public DateTime EffectiveFrom { get; private set; } public DateTime EffectiveTo { get; private set; } public string? Description { get; private set; } public bool IsActive { get; private set; } public DateTime CreatedAtUtc { get; private set; } public Guid? CreatedBy { get; private set; } public DateTime UpdatedAtUtc { get; private set; } public Guid? UpdatedBy { get; private set; } public byte[]? RowVersion { get; private set; }
    public static HotelHousekeepingRuleProfile Create(PropertyId propertyId, string code, string name, HotelHousekeepingRuleKind kind, int priority, string department, int slaMinutes, bool requiresInspection, bool autoCreateTask, DateTime from, DateTime to, string? description, DateTime nowUtc, ActorId? actorId) { Validate(code, name, kind, priority, department, slaMinutes, from, to); return new() { HotelHousekeepingRuleProfileId = Uuid7.NewGuid(), PropertyId = propertyId.Value, Code = CodeValue(code), Name = name.Trim(), Kind = kind, Priority = priority, Department = department.Trim(), SlaMinutes = slaMinutes, RequiresInspection = requiresInspection, AutoCreateTask = autoCreateTask, EffectiveFrom = from.Date, EffectiveTo = to.Date, Description = Normalize(description), IsActive = true, CreatedAtUtc = nowUtc, CreatedBy = actorId?.Value, UpdatedAtUtc = nowUtc, UpdatedBy = actorId?.Value }; }
    public void Update(string code, string name, HotelHousekeepingRuleKind kind, int priority, string department, int slaMinutes, bool requiresInspection, bool autoCreateTask, DateTime from, DateTime to, string? description, DateTime nowUtc, ActorId? actorId) { Validate(code, name, kind, priority, department, slaMinutes, from, to); Code = CodeValue(code); Name = name.Trim(); Kind = kind; Priority = priority; Department = department.Trim(); SlaMinutes = slaMinutes; RequiresInspection = requiresInspection; AutoCreateTask = autoCreateTask; EffectiveFrom = from.Date; EffectiveTo = to.Date; Description = Normalize(description); Touch(nowUtc, actorId); }
    public void Activate(DateTime nowUtc, ActorId? actorId) { IsActive = true; Touch(nowUtc, actorId); } public void Deactivate(DateTime nowUtc, ActorId? actorId) { IsActive = false; Touch(nowUtc, actorId); }
    private static void Validate(string code, string name, HotelHousekeepingRuleKind kind, int priority, string department, int slaMinutes, DateTime from, DateTime to) { if (string.IsNullOrWhiteSpace(code)) throw new ArgumentException("HOTEL_HOUSEKEEPING_RULE_CODE_REQUIRED"); if (string.IsNullOrWhiteSpace(name)) throw new ArgumentException("HOTEL_HOUSEKEEPING_RULE_NAME_REQUIRED"); if (!Enum.IsDefined(kind)) throw new ArgumentException("HOTEL_HOUSEKEEPING_RULE_KIND_INVALID"); if (priority < 0) throw new ArgumentException("HOTEL_HOUSEKEEPING_RULE_PRIORITY_INVALID"); if (string.IsNullOrWhiteSpace(department)) throw new ArgumentException("HOTEL_HOUSEKEEPING_RULE_DEPARTMENT_REQUIRED"); if (slaMinutes < 0) throw new ArgumentException("HOTEL_HOUSEKEEPING_RULE_SLA_INVALID"); if (to.Date < from.Date) throw new ArgumentException("HOTEL_HOUSEKEEPING_RULE_EFFECTIVE_RANGE_INVALID"); }
    private static string CodeValue(string value) => value.Trim().ToUpperInvariant(); private static string? Normalize(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim(); private void Touch(DateTime nowUtc, ActorId? actorId) { UpdatedAtUtc = nowUtc; UpdatedBy = actorId?.Value; }
}
